// Generates Go number-formatting data from pinned CLDR 48 (cldr-numbers-full + cldr-core).
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';

const numdir = 'node_modules/cldr-numbers-full/main';
const locales = readdirSync(numdir).filter(d => {
  try { readFileSync(`${numdir}/${d}/numbers.json`); return true; } catch { return false; }
});

const likely = JSON.parse(readFileSync('node_modules/cldr-core/supplemental/likelySubtags.json')).supplemental.likelySubtags;
const numSystems = JSON.parse(readFileSync('node_modules/cldr-core/supplemental/numberingSystems.json')).supplemental.numberingSystems;
const fractions = JSON.parse(readFileSync('node_modules/cldr-core/supplemental/currencyData.json')).supplemental.currencyData.fractions;

function scriptOf(loc) {
  // exact, then progressively shorter prefixes against likelySubtags
  let l = loc.replace(/-/g, '_');
  for (let s = l; s; s = s.slice(0, s.lastIndexOf('_'))) {
    if (likely[s]) return likely[s].split('_')[1] || 'Zyyy';
    if (s.indexOf('_') < 0) break;
  }
  const lang = l.split('_')[0];
  return likely[lang] ? likely[lang].split('_')[1] : 'Zyyy';
}

const entries = [];
const curSymbols = {};
for (const loc of locales.sort()) {
  const main = JSON.parse(readFileSync(`${numdir}/${loc}/numbers.json`)).main[loc].numbers;
  let currencies = {};
  try { currencies = JSON.parse(readFileSync(`${numdir}/${loc}/currencies.json`)).main[loc].numbers.currencies || {}; } catch {}
  const ns = main.defaultNumberingSystem || 'latn';
  const pick = (group) => main[`${group}-numberSystem-${ns}`] || main[`${group}-numberSystem-latn`] || {};
  const symbols = pick('symbols');
  const dec = pick('decimalFormats').standard || '#,##0.###';
  const pct = pick('percentFormats').standard || '#,##0%';
  const cur = pick('currencyFormats').standard || '¤#,##0.00';
  const curs = {};
  const minGroup = parseInt(main.minimumGroupingDigits || '1', 10);
  for (const [code, info] of Object.entries(currencies)) {
    if (info && info.symbol) curs[code] = info.symbol;
  }
  entries.push({ loc, ns, script: scriptOf(loc), symbols, dec, pct, cur, curs, minGroup });
}

// global currency symbol fallback (en-ish) for locales lacking the code: use en's table
const enEntry = entries.find(e => e.loc === 'en');

let src = `// Code generated by testdata/gen/gen-number-data.mjs from CLDR 48.0. DO NOT EDIT.
package messageformat

type numberLocaleData struct {
	NS         string
	Script     string
	Decimal    string
	Group      string
	Percent    string
	Minus      string
	DecPattern string
	PctPattern string
	CurPattern string
	Currencies map[string]string
	MinGroup   int
}

var cldrNumberData = map[string]numberLocaleData{
`;
for (const e of entries) {
  const s = e.symbols;
  src += `\t${JSON.stringify(e.loc.replace(/-/g, "_"))}: {NS: ${JSON.stringify(e.ns)}, Script: ${JSON.stringify(e.script)}, Decimal: ${JSON.stringify(s.decimal || '.')}, Group: ${JSON.stringify(s.group || ',')}, Percent: ${JSON.stringify(s.percentSign || '%')}, Minus: ${JSON.stringify(s.minusSign || '-')}, DecPattern: ${JSON.stringify(e.dec)}, PctPattern: ${JSON.stringify(e.pct)}, CurPattern: ${JSON.stringify(e.cur)}, Currencies: map[string]string{${Object.entries(e.curs).map(([k, v]) => `${JSON.stringify(k)}: ${JSON.stringify(v)}`).join(', ')}}, MinGroup: ${e.minGroup}},\n`;
}
src += '}\n\nvar cldrNumberSystems = map[string]string{\n';
for (const [ns, info] of Object.entries(numSystems)) {
  if (info._digits) src += `\t${JSON.stringify(ns)}: ${JSON.stringify(info._digits)},\n`;
}
src += '}\n\nvar cldrCurrencyDigits = map[string]int{\n';
for (const [code, info] of Object.entries(fractions)) {
  if (code === 'DEFAULT') continue;
  src += `\t${JSON.stringify(code)}: ${info._digits},\n`;
}
src += `}\n\nvar cldrDefaultCurrencyDigits = ${fractions.DEFAULT._digits}\n`;
src += `\nvar cldrEnCurrencySymbols = map[string]string{${Object.entries(enEntry.curs).map(([k, v]) => `${JSON.stringify(k)}: ${JSON.stringify(v)}`).join(', ')}}\n`;
writeFileSync('../../cldr_number_data.go', src);
console.log(`number data: ${entries.length} locales, ${Object.keys(numSystems).length} numbering systems, ${Object.keys(fractions).length - 1} currencies, ${src.length} bytes`);
